// isStreamingType checks if the data type implements streaming interfaces.
// Thrift codec does not support streaming; use gRPC instead.
func isStreamingType(data interface{}) bool {
	if data == nil {
		return false
	}
	// Check type name for common streaming patterns
	typeName := fmt.Sprintf("%T", data)
	// Common streaming type name patterns
	streamPatterns := []string{
		"Stream", "ClientStream", "ServerStream", "BidiStream",
		"_StreamClient", "_StreamServer", "_StreamingClient", "_StreamingServer",
	}
	for _, pattern := range streamPatterns {
		if len(typeName) > len(pattern) && 
			(typeName[len(typeName)-len(pattern):] == pattern || 
			 fmt.Sprintf("%v", typeName) == pattern) {
			return true
		}
	}
	return false
}

