func isStreamingType(data interface{}) bool {
	if data == nil {
		return false
	}

	rt := reflect.TypeOf(data)
	// Check through pointer/interface wrapping
	for rt.Kind() == reflect.Ptr || rt.Kind() == reflect.Interface {
		rt = rt.Elem()
	}

	typeName := rt.String()

	// Check if type name contains streaming-related patterns
	streamPatterns := []string{
		"Stream", "ClientStream", "ServerStream", "BidiStream",
		"_StreamClient", "_StreamServer", "_StreamingClient", "_StreamingServer",
	}
