// TailOption is a utility function that converts typed options (UnaryOption, StreamOption, TTHeaderStreamingOption)
// back to []Option for use in client initialization.
func TailOption(opts ...interface{}) []Option {
	var result []Option
	for _, opt := range opts {
		switch v := opt.(type) {
		case Option:
			result = append(result, v)
		case UnaryOption:
			result = append(result, Option(v))
		case StreamOption:
			result = append(result, Option(v))
		case TTHeaderStreamingOption:
			result = append(result, Option(v))
		case []Option:
			result = append(result, v...)
		}
	}
	return result
}

